// Layout primitive (Category B): arrangement only, owns no look.
// Carve-out 5 (component-contract.md §6): reads the Sys `text-inset` directly, no Cmp token layer.
// Offsets its children by `text-inset.inline` (component-contract.md §6 rule 8): this is how a Block
// or a consumer applies the inset to text it places beside a rounded box or directly on a painted
// surface. `edge` picks the side: the start (default), the end for end-aligned text (a total
// beside a badge or a button), or both for a line spanning its container.
import type { CSSProperties, ElementType, HTMLAttributes, Ref } from "react";
import "./Indent.css";

type Edge = "start" | "end" | "both";

export interface IndentProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /**
   * Which inline side takes the inset: start, end for end-aligned text, or both.
   *
   * @default "start"
   */
  edge?: Edge;
  /** Render as a different element (e.g. "section", "ul"). */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function Indent({ edge = "start", as: Component = "div", className, ...props }: IndentProps) {
  return (
    <Component
      {...props}
      data-edge={edge === "start" ? undefined : edge}
      className={className ? `sd-indent ${className}` : "sd-indent"}
    />
  );
}

/* Indent.css — .sd-indent
   Layout primitive: arrangement only. Carve-out 5 — reads the Sys text-inset directly (no Cmp
   layer). Moves its children one `text-inset.inline` in from the line (component-contract.md §6
   rule 8): on the start side by default, the end side for end-aligned text (a total beside a
   button), or both for a line spanning its container. Inline only: rule 8 gives
   `text-inset.block` to no part, Indent included. Single class, no descendant combinators. */
.sd-indent {
  padding-inline-start: var(--sd-text-inset-inline);
}

.sd-indent[data-edge="end"] {
  padding-inline-start: 0;
  padding-inline-end: var(--sd-text-inset-inline);
}

.sd-indent[data-edge="both"] {
  padding-inline: var(--sd-text-inset-inline);
}
